const markBlockVolumeDeleting = `-- name: MarkBlockVolumeDeleting :one
UPDATE volumes SET lifecycle = 'deleting'
WHERE id = $1 AND team_id = $2 AND backend = 'block'
  AND lifecycle IN ('ready', 'failed') AND deleted_at IS NULL
RETURNING id, team_id, name, volume_type, created_at, backend, owner_node_id, capacity_bytes, lifecycle, head_incarnation_id, deleted_at
`

type MarkBlockVolumeDeletingParams struct {
	VolumeID uuid.UUID
	TeamID   uuid.UUID
}

// MarkBlockVolumeDeleting blocks new attachments and starts the tombstone.
// It returns no row when the volume is not in a deletable state.
func (q *Queries) MarkBlockVolumeDeleting(ctx context.Context, arg MarkBlockVolumeDeletingParams) (Volume, error) {
	row := q.db.QueryRow(ctx, markBlockVolumeDeleting, arg.VolumeID, arg.TeamID)
	var i Volume
	err := row.Scan(
		&i.ID,
		&i.TeamID,
		&i.Name,
		&i.VolumeType,
		&i.CreatedAt,
		&i.Backend,
		&i.OwnerNodeID,
		&i.CapacityBytes,
		&i.Lifecycle,
		&i.HeadIncarnationID,
		&i.DeletedAt,
	)
	return i, err
}

